// pubspec.yaml:
//   firebase_app_distribution: ^0.2.0  // (Flutter plugin; check current version)

// Note: the Tester SDK is DEBUG / distribution-build ONLY.
// Include in staging flavor, exclude from Play Store release.

import 'package:firebase_app_distribution/firebase_app_distribution.dart';

Future<void> checkForUpdate() async {
  if (!isStagingBuild) return;

  final ad = FirebaseAppDistribution.instance;
  await ad.signInTester();
  final update = await ad.checkForUpdate();
  if (update != null) {
    // Show confirmation dialog — 'v1.2.5 available: fix login crash. Install?'
    final ok = await confirmDialog(context, update);
    if (ok) await ad.updateApp();
  }
}
